using System.IO;
using System.IO.Compression;
using System.Text.Json.Nodes;
namespace Spectra;
public sealed class ThemeLibrary(Store store){
 string Root=>Path.Combine(store.Root,"themes");
 public JsonArray List(){Directory.CreateDirectory(Root);var result=new JsonArray();foreach(var file in Directory.EnumerateFiles(Root,"*.json")){try{result.Add(JsonNode.Parse(File.ReadAllText(file)));}catch{}}return result;}
 public JsonNode Save(JsonNode value){var item=value.DeepClone();var id=item.Str("id");if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"\A[a-f0-9]{32}\z"))id=Guid.NewGuid().ToString("N");item["id"]=id;if(item.Str("name").Length is <1 or >80||item.ToJsonString().Length>8000000)throw new IOException("Invalid theme");item["format"]=1;Directory.CreateDirectory(Root);var path=Path.Combine(Root,id+".json");File.WriteAllText(path+".tmp",item.ToJsonString());File.Move(path+".tmp",path,true);return item;}
 public JsonNode Import(string path){if(new FileInfo(path).Length>8000000)throw new IOException("Theme too large");using var zip=ZipFile.OpenRead(path);if(zip.Entries.Count!=1||zip.Entries[0].FullName!="theme.json"||zip.Entries[0].Length>8000000)throw new IOException("Invalid theme archive");using var reader=new StreamReader(zip.Entries[0].Open());var text=new System.Text.StringBuilder();var buffer=new char[8192];int count;while((count=reader.Read(buffer,0,buffer.Length))>0){if(text.Length+count>8000000)throw new IOException("Theme too large");text.Append(buffer,0,count);}var value=JsonNode.Parse(text.ToString())??throw new IOException("Invalid theme");if(value["format"]?.GetValue<int>()!=1)throw new IOException("Unsupported theme format");value["id"]=Guid.NewGuid().ToString("N");return Save(value);}
 public void Export(JsonNode value,string path){var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var zip=ZipFile.Open(temp,ZipArchiveMode.Create)){using var writer=new StreamWriter(zip.CreateEntry("theme.json",CompressionLevel.Optimal).Open());writer.Write(value.ToJsonString());}File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public JsonNode ReadArchive(string archive){if(archive.Length>700000)throw new IOException("Theme too large");using var memory=new MemoryStream(Convert.FromBase64String(archive));using var zip=new ZipArchive(memory,ZipArchiveMode.Read);if(zip.Entries.Count!=1||zip.Entries[0].FullName!="theme.json"||zip.Entries[0].Length>8000000)throw new IOException("Invalid theme archive");using var reader=new StreamReader(zip.Entries[0].Open());var buffer=new char[8192];var text=new System.Text.StringBuilder();int count;while((count=reader.Read(buffer,0,buffer.Length))>0){if(text.Length+count>8000000)throw new IOException("Theme too large");text.Append(buffer,0,count);}return JsonNode.Parse(text.ToString())??throw new IOException("Invalid theme");}
 public string Encode(JsonNode value){using var memory=new MemoryStream();using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){using var writer=new StreamWriter(zip.CreateEntry("theme.json",CompressionLevel.Optimal).Open());writer.Write(value.ToJsonString());}if(memory.Length>524288)throw new IOException("Workshop theme exceeds 512 KiB compressed");return Convert.ToBase64String(memory.ToArray());}
 public JsonNode ImportWorkshop(string archive,string workshopId){var existing=List().FirstOrDefault(t=>t.Str("workshopId")==workshopId);if(existing!=null)return existing;if(archive.Length>700000)throw new IOException("Theme too large");Directory.CreateDirectory(Root);var path=Path.Combine(Root,Guid.NewGuid().ToString("N")+".spectratheme");try{File.WriteAllBytes(path,Convert.FromBase64String(archive));var value=Import(path);value["origin"]="workshop";value["workshopId"]=workshopId;return Save(value);}finally{if(File.Exists(path))File.Delete(path);}}
 public void Remove(string id){if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"\A[a-f0-9]{32}\z"))throw new IOException("Invalid theme");File.Delete(Path.Combine(Root,id+".json"));}
}
